const fs = require('fs')
const os = require('os')
const path = require('path')
const crypto = require('crypto')
const run_command = require('run-command')

module.exports = theme_folders

// which setting names a theme and what kind of folder it lives in
const theme_settings = [
  { setting: '/org/gnome/desktop/interface/gtk-theme', kind: 'themes' },
  { setting: '/org/gnome/shell/extensions/user-theme/name', kind: 'themes' },
  { setting: '/org/gnome/desktop/interface/icon-theme', kind: 'icons' },
  { setting: '/org/gnome/desktop/interface/cursor-theme', kind: 'icons' }
]

// the themes in use that live in the home folder, as synced keys: /themes/<themes|icons>/<name> -> "'<listing hash>'".
// they are shared as a tar.gz and only ever added, an existing folder is never replaced
function theme_folders ({ dconf, files, env = process.env }) {
  const home = env.HOME || os.homedir()
  const data_dir = env.XDG_DATA_HOME || path.join(home, '.local', 'share')
  const api = { owns: key => key.startsWith('/themes/'), read_all, write, prepare }
  return api

  async function read_all () {
    const all = {}
    for (const { setting, kind } of theme_settings) {
      const name = (await dconf.read(setting))?.slice(1, -1)
      const dir = name && is_valid_name(name) && await find_theme({ kind, name })
      if (dir) all[`/themes/${kind}/${name}`] = `'${await hash_listing(dir)}'`
    }
    return all
  }

  async function prepare (key, value) {
    if (value === null) return
    const { kind, name } = read_key(key)
    const dir = await find_theme({ kind, name })
    await files.publish(key + ' ' + value.slice(1, -1), await pack({ dir, name })) // the key too, two themes can have the same listing
  }

  // null (theme gone on the other device) changes nothing here
  async function write (key, value) {
    if (value === null) return
    const { kind, name } = read_key(key)
    const existing = await find_folder({ kind, name })
    if (existing && `'${await hash_listing(existing)}'` === value) return
    if (existing) throw new Error(`${existing} already exists and is different, not replacing it`)
    await unpack({ data: await files.fetch(key + ' ' + value.slice(1, -1)), name, into: path.join(data_dir, kind) })
  }

  // a real theme has an index.theme (a broken symlink does not count), xdg folder first like gtk
  async function find_theme ({ kind, name }) {
    for (const dir of theme_dirs({ kind, name })) if (await fs.promises.stat(path.join(dir, 'index.theme')).catch(() => null)) return dir
    return null
  }

  async function find_folder ({ kind, name }) {
    for (const dir of theme_dirs({ kind, name })) if (await fs.promises.lstat(dir).catch(() => null)) return dir
    return null
  }

  function theme_dirs ({ kind, name }) { return [path.join(data_dir, kind, name), path.join(home, '.' + kind, name)] }
}

/***************************************
HELPERS
***************************************/
// every file with its size (symlinks with their target), sorted, hashed. same folder on two machines = same hash
async function hash_listing (dir) {
  const names = (await fs.promises.readdir(dir, { recursive: true })).sort()
  const lines = []
  for (const name of names) lines.push(name + ' ' + await describe(path.join(dir, name)))
  return crypto.createHash('sha256').update(lines.join('\n')).digest('hex')
}

async function describe (file) {
  const stat = await fs.promises.lstat(file)
  if (stat.isSymbolicLink()) return 'link ' + await fs.promises.readlink(file)
  return stat.isDirectory() ? 'dir' : 'file ' + stat.size
}

async function pack ({ dir, name }) {
  const archive = temp_file()
  await run_command({ command: 'tar', args: ['-czf', archive, '-C', path.dirname(dir), name] })
  return fs.promises.readFile(archive).finally(() => fs.promises.rm(archive, { force: true }))
}

// every entry has to stay inside <name>/, then it is unpacked
async function unpack ({ data, name, into }) {
  const archive = temp_file()
  await fs.promises.writeFile(archive, data)
  try {
    const entries = (await run_command({ command: 'tar', args: ['-tzf', archive] })).split('\n').filter(Boolean)
    const outside = entries.find(entry => !is_inside({ entry, name }))
    if (outside) throw new Error(`the archive for ${name} has files outside its folder: ${outside}`)
    await fs.promises.mkdir(into, { recursive: true })
    await run_command({ command: 'tar', args: ['-xzf', archive, '-C', into, '--no-same-owner'] })
  } finally {
    await fs.promises.rm(archive, { force: true })
  }
}

function is_inside ({ entry, name }) { return (entry === name + '/' || entry.startsWith(name + '/')) && !entry.split('/').includes('..') }

function read_key (key) {
  const [, , kind, name] = key.split('/')
  if (!['themes', 'icons'].includes(kind) || !is_valid_name(name)) throw new Error('not a valid theme: ' + key)
  return { kind, name }
}

// it becomes a folder name
function is_valid_name (name) { return /^[\w][\w .+@-]*$/.test(name) }

function temp_file () { return path.join(os.tmpdir(), `gnome-hypersync-${process.pid}-${crypto.randomBytes(6).toString('hex')}.tar.gz`) }
